import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"分布式检查点格式","description":"","frontmatter":{"title":"分布式检查点格式","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/distributed-ckpt-format.md","filePath":"llm/distributed-ckpt-format.md","lastUpdated":1789023840000}'),E={name:"llm/distributed-ckpt-format.md"};function c(P,a,m,_,u,A){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="分布式检查点格式" tabindex="-1">分布式检查点格式 <a class="header-anchor" href="#分布式检查点格式" aria-label="Permalink to &quot;分布式检查点格式&quot;">​</a></h1><div class="epigraph"><p>每个 rank 只写自己持有的参数分片，读的时候按新的 TP/PP/EP 度重新切块；检查点是一张可重切的张量地图，不是一份绑死进程数的 pickle。</p><footer>—— 据 PyTorch Distributed Checkpoint 与 Megatron 分布式保存的设计整理</footer></div><p><a href="/llm/async-checkpointing">上一课</a>让 writer 在后台落盘。若格式是「rank i 的 state_dict 整包」，恢复时世界大小一变就读不出来，弹性训练无从做起。本课不重讲异步拷贝。缺口是分片元数据：每块张量的全局形状、沿哪一维切、当前分片偏移，使加载器能把磁盘上的碎片拼成任意并行拓扑下的本地分片。掉卡后的弹性、换机型续训，都吃这张地图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TP 列切的权重、PP 不同阶段、EP 不同专家、ZeRO 切的优化器状态，四套切分可能同时存在。同步 gather 成完整模型再存，体积与带宽都不可接受，也破坏异步。必须分布式写。读侧却经常换拓扑：调试用更小 TP，生产用更大 EP。格式若把 rank 号写死，等于把并行策略焊进磁盘。</p><p>元数据还要版本化：字段增删、dtype（BF16 参数 + FP32 矩）、MoE 专家数变化，都要能拒绝加载或做声明过的转换，而不是静默 reshape 成功。</p><h3 id="与词表、数据游标" tabindex="-1">与词表、数据游标 <a class="header-anchor" href="#与词表、数据游标" aria-label="Permalink to &quot;与词表、数据游标&quot;">​</a></h3><p>嵌入矩阵随词表扩展加行，检查点必须记录 \\(|V|\\) 与 id 契约。数据游标、RNG、累积进度、退火阶段号，与权重同一清单发布。缺一项，训练重放课无法对齐。</p><p><span class="marginnote">「每个 rank 一个文件」在百万文件的并行文件系统上会崩溃。应聚合成有界数量的分片文件，由元数据索引，而不是进程数等于文件数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>采用显式的 tensor-shard 表：逻辑名、全局 shape、切分轴、dtype、校验和、文件偏移。PyTorch DCP、Megatron dist-ckpt 走这一路。写时只写本地分片；读时根据当前并行计划计算需要的字节范围，可能从多个文件 gather 再 scatter 到本地。改 PP 度等于按层边界重新分组，不改权重数值。改 TP 度等于沿隐藏维重切。改 EP 度等于专家列表重分配。</p><p>发布过程：所有 writer 完成后写一份不可变的 metadata.json（或等价），再用原子替换更新「latest」指针。异步课的全局 AND 完成标志，指的就是这份 metadata 的发布。</p><h3 id="校验与部分加载" tabindex="-1">校验与部分加载 <a class="header-anchor" href="#校验与部分加载" aria-label="Permalink to &quot;校验与部分加载&quot;">​</a></h3><p>允许只加载模型不加载优化器（推理或换优化器），但必须显式。部分专家缺失应失败。嵌入行数与当前词表不一致应失败或走扩展课的加行协议，禁止截断静默发生。</p><p><span class="marginnote">跨精度续训（FP8 权重如何还原）要有文档化的反量化，不属于本课发明格式，但元数据必须标注量化方案。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>检查点是参数张量在存储上的另一种并行布局。训练时的布局为计算与通信优化；存储布局为持久化与重切优化。两者通过元数据同构。弹性训练改变的是计算布局，不改变逻辑张量；格式是同构的见证。</p>',17)),(e(),n(h,null,{default:r(()=>[p(i,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOC%5B%22%E5%90%84%20rank%20%E6%9C%AC%E5%9C%B0%E5%88%86%E7%89%87%22%5D%20--%3E%20OBJ%5B%22%E6%9C%89%E7%95%8C%E5%AF%B9%E8%B1%A1%E6%96%87%E4%BB%B6%22%5D%0A%20%20OBJ%20--%3E%20META%5B%22%E5%85%A8%E5%B1%80%E5%BC%A0%E9%87%8F%E5%9C%B0%E5%9B%BE%22%5D%0A%20%20META%20--%3E%20PLAN%5B%22%E6%96%B0%E5%B9%B6%E8%A1%8C%E8%AE%A1%E5%88%92%22%5D%0A%20%20PLAN%20--%3E%20GATH%5B%22%E6%8C%89%E9%9C%80%20gather%2Fscatter%22%5D%0A%20%20GATH%20--%3E%20NEW%5B%22%E6%96%B0%E4%B8%96%E7%95%8C%E7%9A%84%E6%9C%AC%E5%9C%B0%E5%88%86%E7%89%87%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>格式不提高保存带宽；异步与并行文件系统仍然决定墙钟。它也不能把不兼容的结构（层数变了）变兼容。下一课在这张可重切地图上做世界大小变化：掉卡后少几台机器继续训，或加机器加速，而不从头读一个假想的完整权重。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲异步 IO；只补可重切的分片元数据。</li><li>逻辑张量 + 切分轴 + 有界文件 + 原子 metadata 发布。</li><li>改 TP/PP/EP 是重切不是换模型；词表行数与游标必须同清单。</li><li>rank 号不得焊进唯一可读路径。</li><li>出处：PyTorch Distributed Checkpoint；Megatron 分布式检查点；对照 ZeRO 分片状态。</li></ul>',4))])}const T=o(E,[["render",c]]);export{k as __pageData,T as default};
